<?php declare(strict_types=1);$editing=$post!==null;?><div class="mb-5"><a class="text-sm font-semibold text-navy-700" href="<?= e(admin_url('blog')) ?>">← Back to blogs</a></div><form class="card max-w-4xl p-6" method="post" action="<?= e($editing?admin_url('blog/'.$post['id']):admin_url('blog')) ?>"><?= csrf_field() ?><div class="grid gap-5 sm:grid-cols-2"><div class="sm:col-span-2"><label class="field-label">Title</label><input class="field" required name="title" maxlength="200" value="<?= e($post['title']??'') ?>"></div><div><label class="field-label">URL slug</label><input class="field" name="slug" maxlength="200" value="<?= e($post['slug']??'') ?>"></div><div><label class="field-label">Category</label><select class="field" name="category_id"><option value="0">Uncategorised</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= (int)($post['category_id']??0)===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></div><div class="sm:col-span-2"><label class="field-label">Excerpt</label><textarea class="field h-auto py-3" rows="3" name="excerpt"><?= e($post['excerpt']??'') ?></textarea></div><div class="sm:col-span-2"><label class="field-label">Article body</label><textarea class="field h-auto py-3" rows="16" name="body"><?= e($post['body']??'') ?></textarea><p class="mt-1 t-meta text-muted">Start a line with ## for a section heading.</p></div><div><label class="field-label">Cover image</label><select class="field" name="cover_id"><option value="0">None</option><?php foreach($media as $m): ?><option value="<?= $m['id'] ?>" <?= (int)($post['cover_id']??0)===(int)$m['id']?'selected':'' ?>><?= e($m['alt'].' — '.$m['path']) ?></option><?php endforeach; ?></select></div><div><label class="field-label">Reading time</label><input class="field" type="number" min="1" max="255" name="read_minutes" value="<?= (int)($post['read_minutes']??5) ?>"></div><label><input type="checkbox" name="featured" <?= !empty($post['featured'])?'checked':'' ?>> Featured</label><label><input type="checkbox" name="published" <?= !empty($post['published_at'])?'checked':'' ?>> Published</label></div><button class="btn btn-primary mt-7">Save article</button></form>
